async function api(url,options={}){
 const headers={...options.headers};if(options.body && !(options.body instanceof FormData)){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}
 if(options.method && options.method!=='GET')headers['X-CSRFToken']=decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('csrftoken='))?.split('=')[1]||'');
 const response=await fetch('/api/'+url,{...options,headers});let result;try{result=await response.json()}catch{throw Error('服务响应异常，请检查本地服务是否运行')}
 if(!response.ok){if(response.status===401 && url!=='auth'){state.user=null;showLogin()}const error=Error(result.error||'操作失败');error.status=response.status;error.code=result.code;throw error}return result;
}
