function chart(rows,label='name',value='value',kind='bar',second=null,interactive=false){
 if(!rows.length)return '<div class="empty">此筛选范围暂无可显示数据</div>';
 const numeric=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
 const selection=(r,side='primary')=>interactive&&Number.isInteger(r._topic_link_i)&&r._topic_link_i>=0?` data-topic-link-index="${r._topic_link_i}" data-topic-link-side="${side}" role="button" tabindex="0" aria-label="联动筛选 ${esc(r[label])}"`:'';
 const allValues=rows.flatMap(r=>[r[value],...(second?[r[second]]:[])]).filter(numeric).map(Number);
 if(!allValues.length)return '<div class="empty">无有效数值或分母为零，暂不能绘图。明细保留为空。</div>';
 if(kind==='donut'){
  if(allValues.some(v=>v<0))return '<div class="empty">存在负值，无法表示非负总量构成；请改用柱图或表格。</div>';
  const valid=rows.filter(r=>numeric(r[value])),missing=rows.length-valid.length,total=valid.reduce((s,r)=>s+Number(r[value]),0);
  if(!total)return '<div class="empty">汇总值为零，无占比可展示。</div>';
  const shown=valid.slice(0,8);if(valid.length>8)shown.push({[label]:'其余 '+(valid.length-8)+' 组',[value]:valid.slice(8).reduce((s,r)=>s+Number(r[value]),0)});
  let offset=0;const colors=['#1d6551','#8dac61','#b8ce8f','#d2a068','#788e9d','#c7cfb9','#859574','#d4c5a2','#b0b6ad'],circ=2*Math.PI*74;
  const circles=shown.map((r,i)=>{const pct=Number(r[value])/total,mark=`<circle${selection(r)} cx="155" cy="118" r="74" fill="none" stroke="${colors[i]}" stroke-width="31" stroke-dasharray="${pct*circ} ${circ-pct*circ}" stroke-dashoffset="${-offset}" transform="rotate(-90 155 118)"><title>${esc(r[label])}：${num(r[value],2)} · ${num(pct*100,2)}%</title></circle>`;offset+=pct*circ;return mark});
  return `<svg class="chart" viewBox="0 0 640 246" role="img" aria-label="分类占比图">${circles.join('')}<text x="155" y="117" text-anchor="middle" style="font-size:26px;fill:#24332f">${num(total,1)}</text><text x="155" y="139" text-anchor="middle">汇总</text>${shown.map((r,i)=>`<rect x="290" y="${25+i*23}" width="8" height="8" rx="2" fill="${colors[i]}"/><text x="308" y="${33+i*23}"><title>${esc(r[label])}</title>${esc(String(r[label]).slice(0,21))}</text><text x="625" y="${33+i*23}" text-anchor="end">${num(r[value],1)} · ${num(r[value]/total*100,1)}%</text>`).join('')}</svg>${valid.length>8?'<p class="panel-note">前8组与其余组；占比按全部有效分组总量计算。</p>':''}${missing?`<p class="panel-note">${missing} 个分组缺少数值，未计入可知总量。</p>`:''}`;
 }
 const shown=rows.slice(0,18),w=640,h=246,left=42,right=15,top=22,bottom=47,cw=w-left-right,ch=h-top-bottom;
 const values=shown.flatMap(r=>[r[value],...(second?[r[second]]:[])]).filter(numeric).map(Number),max=Math.max(...values,1),min=Math.min(...values,0),range=max-min||1,y=v=>top+ch-(v-min)/range*ch,step=cw/shown.length;
 const axes=[0,.25,.5,.75,1].map(f=>{const v=min+range*f;return `<line class="axis" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+3}" text-anchor="end">${num(v,Math.abs(v)<10?1:0)}</text>`}).join('');
 let marks='';
 if(kind==='line'){
  let segment=[];const segments=[];shown.forEach((r,i)=>{if(numeric(r[value]))segment.push([left+step*(i+.5),y(Number(r[value]))]);else{if(segment.length)segments.push(segment);segment=[]}});if(segment.length)segments.push(segment);
  marks=segments.map(points=>`<polyline class="line" points="${points.map(p=>p.join(',')).join(' ')}"/>`).join('')+shown.map((r,i)=>numeric(r[value])?`<circle${selection(r)} cx="${left+step*(i+.5)}" cy="${y(Number(r[value]))}" r="4" fill="#1d6551" stroke="white" stroke-width="2"><title>${esc(r[label])}：${num(r[value],2)}</title></circle>`:`<text class="missing" x="${left+step*(i+.5)}" y="${y(0)-9}" text-anchor="middle"><title>${esc(r[label])}：无有效值</title>—</text>`).join('');
 }else marks=shown.map((r,i)=>{const bw=Math.min(38,step*(second?.32:.54));return [value,...(second?[second]:[])].map((k,j)=>{const x=left+step*(i+.5)-bw*(second?1:.5)+(j*bw);if(!numeric(r[k]))return `<text class="missing" x="${x+bw/2}" y="${y(0)-9}" text-anchor="middle"><title>${esc(r[label])}：无有效值</title>—</text>`;const v=Number(r[k]);return `<rect${selection(r,j?'reference':'primary')} class="${j?'bar-secondary':'bar'}" x="${x}" y="${Math.min(y(v),y(0))}" width="${bw-2}" height="${Math.max(Math.abs(y(v)-y(0)),v===0?0:1)}" rx="3"><title>${esc(r[label])}：${num(v,2)}</title></rect>`}).join('')}).join('');
 const labels=shown.map((r,i)=>`<text x="${left+step*(i+.5)}" y="${h-23}" text-anchor="middle"><title>${esc(r[label])}</title>${esc(String(r[label]).replace(/^2026-/,'').slice(0,12))}</text>`).join('');
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${kind==='line'?'趋势':'对比'}图">${axes}${marks}${labels}</svg>${rows.length>18?'<p class="panel-note">图形显示前18组；其余分组请缩小范围或查看完整分析结果。</p>':''}`;
}
