 on('#family','change',e=>go('overview',{family:e.target.value,preset:presentation.preset}));on('#overview-preset','change',e=>go('overview',{family,preset:e.target.value}));on('#refresh','click',()=>renderOverview(params,token));$$('[data-issue-link]').forEach(b=>b.addEventListener('click',()=>go('issues',{family,kind:b.dataset.issueLink})));$$('[data-order]').forEach(b=>b.addEventListener('click',()=>go('delivery',{line:b.dataset.order,family})));
